// AUTO-GENERATED by Bloxks — do not edit. Overwritten on every build.
// Apple-required paywall footer (guideline 3.1.2): real price and period, free trial,
// auto-renewal terms, Restore Purchases, Terms of Use and Privacy Policy.
// Put it at the bottom of every paywall:
//   <PaywallLegalFooter pkg={selectedPackage} onRestored={(active) => active && onDismiss?.()} />
import React, { useState } from 'react'
import { ActivityIndicator, Linking, Platform, Pressable, Text, View, type StyleProp, type ViewStyle } from 'react-native'
import type { PurchasesPackage } from './revenueCat'
import { ZZZ_LEGAL } from './legalLinks'
import { fallbackPrice, productPeriod, productTrialDuration, restorePurchases } from './revenueCat'

type Lang = 'fr' | 'en'

const PERIOD: Record<string, [string, string]> = {
  weekly: ['semaine', 'week'],
  monthly: ['mois', 'month'],
  two_months: ['2 mois', '2 months'],
  three_months: ['3 mois', '3 months'],
  six_months: ['6 mois', '6 months'],
  annual: ['an', 'year'],
}

const TRIAL: Record<string, [string, string]> = {
  THREE_DAYS: ['3 jours', '3 days'],
  ONE_WEEK: ['1 semaine', '1 week'],
  TWO_WEEKS: ['2 semaines', '2 weeks'],
  ONE_MONTH: ['1 mois', '1 month'],
  TWO_MONTHS: ['2 mois', '2 months'],
  THREE_MONTHS: ['3 mois', '3 months'],
  SIX_MONTHS: ['6 mois', '6 months'],
  ONE_YEAR: ['1 an', '1 year'],
}

function deviceLang(): Lang {
  try {
    return Intl.DateTimeFormat().resolvedOptions().locale.toLowerCase().startsWith('fr') ? 'fr' : 'en'
  } catch {
    return 'en'
  }
}

export interface PaywallLegalFooterProps {
  /** Package sélectionné (offering RevenueCat). Son prix réel prime sur le prix de repli. */
  pkg?: PurchasesPackage | null
  /** Identifiant produit, si aucun package n'est encore chargé. */
  productId?: string
  /** Appelé après « Restaurer » : true si l'accès est rétabli. */
  onRestored?: (entitlementActive: boolean) => void
  lang?: Lang
  color?: string
  style?: StyleProp<ViewStyle>
  termsUrl?: string
  privacyUrl?: string
}

export function PaywallLegalFooter({
  pkg,
  productId,
  onRestored,
  lang,
  color = 'rgba(255,255,255,0.6)',
  style,
  termsUrl,
  privacyUrl,
}: PaywallLegalFooterProps): React.ReactElement {
  const l = lang ?? deviceLang()
  const i = l === 'fr' ? 0 : 1
  const [restoring, setRestoring] = useState(false)
  const [restoreMessage, setRestoreMessage] = useState<string | null>(null)
  const terms = termsUrl ?? ZZZ_LEGAL.termsUrl
  const privacy = privacyUrl ?? ZZZ_LEGAL.privacyUrl

  // Le package entier, pas son identifiant : sur Google Play celui-ci vaut
  // « abonnement:plan de base » et ne retrouve pas seul la cadence du catalogue.
  const ref = pkg ?? productId ?? ''
  const price = pkg?.product.priceString ?? (ref ? fallbackPrice(ref) : null)
  const period = ref ? productPeriod(ref) : null
  const trial = ref ? TRIAL[productTrialDuration(ref)] : undefined
  const lifetime = period === 'lifetime' || period === 'consumable'
  const per = period && PERIOD[period] ? PERIOD[period][i] : null

  let terms_line: string
  if (lifetime) {
    terms_line = l === 'fr'
      ? `Achat unique${price ? ` de ${price}` : ''}, sans abonnement.`
      : `One-time purchase${price ? ` of ${price}` : ''}, no subscription.`
  } else {
    const billed = price && per ? (l === 'fr' ? `${price} par ${per}` : `${price} per ${per}`) : null
    const head = trial
      ? (l === 'fr' ? `${trial[0]} gratuits, puis ${billed ?? 'le prix affiché'}.` : `${trial[1]} free, then ${billed ?? 'the price shown'}.`)
      : (billed ? `${billed}.` : '')
    // Android : l'abonnement se gère dans Google Play, jamais « App Store ».
    const store = Platform.OS === 'android' ? 'Google Play' : 'App Store'
    terms_line = l === 'fr'
      ? `${head} L’abonnement se renouvelle automatiquement, sauf résiliation au moins 24 h avant la fin de la période en cours. Annulable à tout moment dans les réglages de ton compte ${store}.`.trim()
      : `${head} The subscription renews automatically unless cancelled at least 24 hours before the end of the current period. Cancel anytime in your ${store} account settings.`.trim()
  }

  async function restore(): Promise<void> {
    setRestoring(true)
    setRestoreMessage(null)
    const r = await restorePurchases()
    setRestoring(false)
    setRestoreMessage(
      r.entitlementActive
        ? (l === 'fr' ? 'Achats restaurés.' : 'Purchases restored.')
        : (l === 'fr' ? 'Aucun achat à restaurer.' : 'No purchases to restore.'),
    )
    onRestored?.(r.entitlementActive)
  }

  const link = { color, fontSize: 12, textDecorationLine: 'underline' as const, paddingVertical: 10, paddingHorizontal: 6 }
  return (
    <View style={[{ alignItems: 'center', paddingTop: 8 }, style]}>
      <Text style={{ color, fontSize: 11, lineHeight: 15, textAlign: 'center' }}>{terms_line}</Text>
      <View style={{ flexDirection: 'row', flexWrap: 'wrap', justifyContent: 'center', alignItems: 'center', marginTop: 4 }}>
        <Pressable accessibilityRole="button" onPress={() => void restore()} disabled={restoring} hitSlop={8}>
          {restoring ? <ActivityIndicator size="small" color={color} /> : (
            <Text style={link}>{l === 'fr' ? 'Restaurer les achats' : 'Restore Purchases'}</Text>
          )}
        </Pressable>
        {terms ? (
          <Pressable accessibilityRole="link" onPress={() => void Linking.openURL(terms)} hitSlop={8}>
            <Text style={link}>{l === 'fr' ? 'Conditions d’utilisation' : 'Terms of Use'}</Text>
          </Pressable>
        ) : null}
        {privacy ? (
          <Pressable accessibilityRole="link" onPress={() => void Linking.openURL(privacy)} hitSlop={8}>
            <Text style={link}>{l === 'fr' ? 'Confidentialité' : 'Privacy Policy'}</Text>
          </Pressable>
        ) : null}
      </View>
      {restoreMessage ? <Text style={{ color, fontSize: 11, marginTop: 2 }}>{restoreMessage}</Text> : null}
    </View>
  )
}
